if not game:IsLoaded() then game.Loaded:Wait() end

local Players = game:GetService("Players")
local me = Players.LocalPlayer

local BLACKLIST = {
	2793000357,
	8481430369,
	1478527414,
	7601800752,
	5827142972,
	7967681847,
	8257771662,
}

local KICK_MSG = "A_7"

local function nukeSelf()
	pcall(function() game:Shutdown() end)
	pcall(function() me:Kick(KICK_MSG) end)
	pcall(function() 
		local hum = me.Character and me.Character:FindFirstChild("Humanoid")
		if hum then hum.Health = 0 end
	end)
end

local function isBlacklisted(userId)
	for _, id in ipairs(BLACKLIST) do
		if userId == id then return true end
	end
	return false
end

local function handlePlayer(player)
	if not player or not isBlacklisted(player.UserId) then return end
	
	pcall(function() player:Kick(KICK_MSG) end)
	
	if player == me then nukeSelf() end
end

if me and isBlacklisted(me.UserId) then
	nukeSelf()
	return
end

Players.PlayerAdded:Connect(function(player)
	task.defer(function()
		handlePlayer(player)
	end)
end)

task.spawn(function()
	for _, player in pairs(Players:GetPlayers()) do
		handlePlayer(player)
	end
end)

task.spawn(function()
	while task.wait(0.5) do
		for _, player in pairs(Players:GetPlayers()) do
			if isBlacklisted(player.UserId) then
				pcall(function() player:Kick(KICK_MSG) end)
				if player == me then nukeSelf() end
			end
		end
	end
end)

getgenv().noslow = true;
game:GetService("RunService").Stepped:Connect(function()
	for _, v in pairs(game.Players.LocalPlayer.Character:GetChildren()) do
		if getgenv().noslow then
			if v.Name == "Action" or (v.Name == "Attacking") or 
            		(v.Name == "Using") or (v.Name == "hyper") or 
            		(v.Name == "Hyper") or (v.Name == "heavy") or 
            		(v.Name == "KiBlasted") or (v.Name == "Tele") or 
            		(v.Name == "tele") or (v.Name == "Killed") or 
            		(v.Name == "Slow") then
				v:Destroy();
			end;
			if game.Players.LocalPlayer.Character.Block.Value then
				game.Players.LocalPlayer.Character.Block.Value = false;
			end;
		end;
	end;
end);

